import { useEffect, useState } from 'react'
import { useNavigate, useParams } from 'react-router-dom'
import { App, Button, Card, Form, Input, Select, Space, Upload } from 'antd'
import type { UploadRequestOption } from 'antd/es/upload/interface'
import {
  createDrama,
  getAdminDrama,
  updateDrama,
  uploadFile,
  type DramaSaveRequest,
} from '../api/admin'
import { getApiErrorMessage } from '../api/client'

interface DramaFormValues {
  title: string
  description: string
  category: string
  coverUrl: string
  status: string
}

/** 短剧表单（新增/编辑共用）：封面 Upload 直传后把返回 URL 填入表单（计划任务4 第4条）。 */
export default function DramaFormPage() {
  const { id } = useParams()
  const isEdit = !!id
  const { message } = App.useApp()
  const navigate = useNavigate()
  const [form] = Form.useForm<DramaFormValues>()
  const [coverUrl, setCoverUrl] = useState('')
  const [saving, setSaving] = useState(false)
  const [loading, setLoading] = useState(isEdit)

  useEffect(() => {
    if (!isEdit) {
      return
    }
    getAdminDrama(id)
      .then((detail) => {
        form.setFieldsValue(detail)
        setCoverUrl(detail.coverUrl)
      })
      .catch((err) => message.error(getApiErrorMessage(err)))
      .finally(() => setLoading(false))
  }, [id, isEdit, form, message])

  const customUpload = async (options: UploadRequestOption) => {
    const { file, onSuccess, onError } = options
    try {
      const url = await uploadFile(file as File, 'cover')
      setCoverUrl(url)
      form.setFieldValue('coverUrl', url)
      message.success('封面上传成功')
      onSuccess?.(url)
    } catch (err) {
      message.error(getApiErrorMessage(err))
      onError?.(err as Error)
    }
  }

  const onFinish = async (values: DramaFormValues) => {
    setSaving(true)
    try {
      if (isEdit) {
        await updateDrama(id, values)
        message.success('保存成功')
      } else {
        await createDrama(values)
        message.success('新增成功')
      }
      navigate('/')
    } catch (err) {
      message.error(getApiErrorMessage(err))
    } finally {
      setSaving(false)
    }
  }

  return (
    <Card title={isEdit ? `编辑短剧 #${id}` : '新增短剧'} loading={loading}>
      <Form<DramaFormValues>
        form={form}
        layout="vertical"
        style={{ maxWidth: 560 }}
        initialValues={{ status: 'ONLINE', description: '' }}
        onFinish={(values) => void onFinish(values)}
      >
