const tab = await browser.tabs.get(adminTab.id);

// 1) 填文本字段
await tab.playwright.evaluate(() => {
  const setter = Object.getOwnPropertyDescriptor(window.HTMLInputElement.prototype, "value").set;
  const taSetter = Object.getOwnPropertyDescriptor(window.HTMLTextAreaElement.prototype, "value").set;
  const title = [...document.querySelectorAll("input")].find((i) => i.placeholder.includes("剧名"));
  const cat = [...document.querySelectorAll("input")].find((i) => i.placeholder.includes("甜宠"));
  setter.call(title, "门禁演示剧");
  title.dispatchEvent(new Event("input", { bubbles: true }));
  setter.call(cat, "甜宠");
  cat.dispatchEvent(new Event("input", { bubbles: true }));
  const desc = document.querySelector("textarea");
  if (desc) { taSetter.call(desc, "验收门禁专用：后台新增短剧全链路演示"); desc.dispatchEvent(new Event("input", { bubbles: true })); }
});

// 2) 抓取已有 jpg 封面字节，经 3001 代理同源 fetch，DataTransfer 注入 file input
const injected = await tab.playwright.evaluate(async () => {
  const res = await fetch("/uploads/files/b9adb9ba-5cc0-4d38-8e82-4a47c34c65c7.jpg");
  const blob = await res.blob();
  const file = new File([blob], "cover.jpg", { type: "image/jpeg" });
  const input = document.querySelector('input[type=file]');
  if (!input) return "no-input";
  const dt = new DataTransfer();
  dt.items.add(file);
  input.files = dt.files;
  input.dispatchEvent(new Event("change", { bubbles: true }));
  return `injected ${blob.size} bytes`;
});
nodeRepl.write("注入: " + injected);

