const audit = async (tab, label) => {
  const ext = await tab.playwright.evaluate(() => {
    const bad = [];
    for (const e of performance.getEntriesByType("resource")) {
      const u = new URL(e.name, location.href);
      if (!/^(localhost|127\.0\.0\.1)$/.test(u.hostname)) bad.push(e.name);
    }
    // 页面里显式引用的外链（img src / link href / 字体）
    for (const el of document.querySelectorAll("img[src], link[href], script[src]")) {
      const v = el.getAttribute("src") || el.getAttribute("href") || "";
      if (/^https?:\/\//.test(v) && !/localhost|127\.0\.0\.1/.test(v)) bad.push(v);
    }
    return bad;
  });
  return label + ": " + (ext.length ? "外部资源 " + JSON.stringify(ext) : "全部本机 ✓");
};

